import styled from "styled-components";
import Col from "react-bootstrap/Col";

export const TopBanner = styled(Col)`
  background: radial-gradient(67.22% 50% at 50% 50%, rgba(26, 105, 179, 0.15) 0%, rgba(245, 228, 255, 0) 100%);
  padding: 40px;
`
